/**
 * Report assets embedded as base64 data URIs.
 *
 * The NSPIRE report HTML is rendered in contexts with no reliable base URL or
 * network access — a detached iframe (lib/exportReportPdf.ts), a blob: document,
 * and window.open('') — so relative paths like /logo.png and remote URLs fail to
 * load and rasterize as broken images in the exported PDF. Inlining the logo keeps
 * the generated report fully self-contained.
 *
 * Source: public/report-logo.png (cropped + downscaled from public/logo.png).
 */
export const NSPIRE_LOGO_DATA_URI =
  'data:image/png;base64,'
